/**
 * Love Meter ❤️ — Audio module.
 *
 * Uses the Web Audio API for sound effects and plays a generated ambient
 * music loop (public/assets/audio/love-theme.wav) for the music toggle.
 *
 * No external dependencies or audio files are required at runtime — the WAVs
 * are generated by `npm run audio`.
 */

let audioCtx = null;
let musicSource = null;
let musicGain = null;
let musicEnabled = false;

function getContext() {
  if (!audioCtx) {
    try {
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    } catch {
      return null;
    }
  }
  if (audioCtx.state === 'suspended') {
    try { audioCtx.resume(); } catch { /* ignore */ }
  }
  return audioCtx;
}

export function isSoundEnabled() {
  return localStorage.getItem('lm_sound') !== 'off';
}

export function toggleSound() {
  const current = isSoundEnabled();
  localStorage.setItem('lm_sound', current ? 'off' : 'on');
  return !current;
}

/** Load a WAV file and decode it into an AudioBuffer. */
async function loadAudio(url) {
  const ctx = getContext();
  if (!ctx) return null;
  try {
    const res = await fetch(url);
    if (!res.ok) return null;
    const arrayBuffer = await res.arrayBuffer();
    return await ctx.decodeAudioData(arrayBuffer);
  } catch {
    return null;
  }
}

/** Play a short one-shot audio buffer (click, success, heartbeat). */
function playBuffer(buffer, volume = 0.5) {
  const ctx = getContext();
  if (!ctx || !buffer) return;
  try {
    const src = ctx.createBufferSource();
    const gain = ctx.createGain();
    src.buffer = buffer;
    gain.gain.value = volume;
    src.connect(gain);
    gain.connect(ctx.destination);
    src.start(ctx.currentTime);
  } catch { /* ignore */ }
}

let clickBuffer = null;
let successBuffer = null;
let heartbeatBuffer = null;

/** Preload sound effect buffers (call once from UI init). */
export function preloadAudio() {
  loadAudio('/assets/audio/click.wav').then(b => { clickBuffer = b; });
  loadAudio('/assets/audio/success.wav').then(b => { successBuffer = b; });
  loadAudio('/assets/audio/heartbeat.wav').then(b => { heartbeatBuffer = b; });
}

export function playClick() {
  if (!isSoundEnabled()) return;
  if (clickBuffer) return playBuffer(clickBuffer, 0.4);
  // Fallback: synthesized click
  const ctx = getContext();
  if (!ctx) return;
  try {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.frequency.value = 1200;
    osc.type = 'sine';
    gain.gain.value = 0.12;
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.08);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + 0.08);
  } catch { /* ignore */ }
}

export function playSuccess() {
  if (!isSoundEnabled()) return;
  if (successBuffer) return playBuffer(successBuffer, 0.5);
  const ctx = getContext();
  if (!ctx) return;
  try {
    const notes = [523, 659, 784];
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.frequency.value = freq;
      osc.type = 'sine';
      gain.gain.value = 0.08;
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3 + i * 0.15);
      osc.start(ctx.currentTime + i * 0.15);
      osc.stop(ctx.currentTime + 0.3 + i * 0.15);
    });
  } catch { /* ignore */ }
}

export function playHeartbeat() {
  if (!isSoundEnabled()) return;
  if (heartbeatBuffer) return playBuffer(heartbeatBuffer, 0.6);
  const ctx = getContext();
  if (!ctx) return;
  try {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain);
    gain.connect(ctx.destination);
    osc.frequency.value = 60;
    osc.type = 'sine';
    gain.gain.value = 0.15;
    gain.gain.setValueAtTime(0.15, ctx.currentTime);
    gain.gain.setValueAtTime(0, ctx.currentTime + 0.08);
    gain.gain.setValueAtTime(0.12, ctx.currentTime + 0.15);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + 0.4);
  } catch { /* ignore */ }
}

// ---------------------------------------------------------------------------
// Background music (loop)
// ---------------------------------------------------------------------------

export function isMusicEnabled() {
  return localStorage.getItem('lm_music') !== 'off';
}

/** Start the ambient music loop (must be called after a user gesture). */
export async function playMusic() {
  const ctx = getContext();
  if (!ctx) return;
  if (musicSource) return; // already playing

  const buffer = await loadAudio('/assets/audio/love-theme.wav');
  if (!buffer) return;

  try {
    musicSource = ctx.createBufferSource();
    musicSource.buffer = buffer;
    musicSource.loop = true;

    musicGain = ctx.createGain();
    musicGain.gain.value = 0.35;

    musicSource.connect(musicGain);
    musicGain.connect(ctx.destination);
    musicSource.start(ctx.currentTime);
  } catch { /* ignore */ }
}

/** Stop the ambient music loop. */
export function stopMusic() {
  if (musicSource) {
    try {
      musicSource.stop();
    } catch { /* ignore */ }
    musicSource.disconnect();
    musicSource = null;
  }
  if (musicGain) {
    musicGain.disconnect();
    musicGain = null;
  }
}

/** Toggle music on/off. Returns the new enabled state. */
export function toggleMusic() {
  const next = !isMusicEnabled();
  localStorage.setItem('lm_music', next ? 'on' : 'off');
  if (next) {
    playMusic();
  } else {
    stopMusic();
  }
  return next;
}

